import base64
import re

prompt_str = base64.b64decode('').decode('utf-8')

with open('brain/planner.py', 'r', encoding='utf-8') as f:
    content = f.read()

pattern = re.compile(r'AMV_SYSTEM_PROMPT = \"\"\"\\\\.*?^\"\"\"\\n', re.DOTALL | re.MULTILINE)
new_content = pattern.sub('AMV_SYSTEM_PROMPT = \"\"\"\\n' + prompt_str + '\"\"\"\\n', content)

with open('brain/planner.py', 'w', encoding='utf-8') as f:
    f.write(new_content)
print('Updated AMV_SYSTEM_PROMPT')
